function showExample(el,c,u,i){var host=el.querySelector('#um-'+i);var ex=(c.examples||[])[0];if(!host)return;if(!ex){host.innerHTML='<div class="v87-explainer"><h3>Beispiel</h3><p>'+esc(firstSentence((u.body||[]).join(' ')))+'</p><p>Formuliere dazu selbst einen konkreten Fall und prüfe, ob der Zusammenhang unverändert gilt.</p></div>';return;}host.innerHTML='<div class="v87-explainer"><h3>Beispiel</h3><p><b>'+esc(strip(ex.task||''))+'</b></p><ol>'+((ex.steps||[]).map(function(s){return'<li>'+esc(strip(typeof s==='string'?s:s.do||''))+'</li>';}).join(''))+'</ol>'+(ex.result?'<p><b>Ergebnis:</b> '+esc(strip(ex.result))+'</p>':'')+'</div>';}
