function makeVisualsClickable(el){el.querySelectorAll('.figure,.fig,.viz').forEach(function(f){if(f.dataset.v87Visual)return;f.dataset.v87Visual='1';f.classList.add('v87-visual-open');f.tabIndex=0;f.setAttribute('role','button');f.setAttribute('aria-label','Darstellung vergrössern');var open=function(){openModal('Darstellung vergrössert','', '<div class="v87-large">'+f.innerHTML+'</div>','v87-visual-modal');};f.onclick=open;f.onkeydown=function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();open();}};});}
function openAI(c,u){if(M.kiTutor&&M.kiTutor.open)return M.kiTutor.open(c,u); /* R105: ein Besitzer fuer KI-Hilfe */var concept=u&&u.concept||c.title,body=strip((u&&u.body||[]).join(' '));var levels=['Sehr einfach','Mit einem Beispiel','Schritt für Schritt','Prüfungsnah'];var html='<div class="v87-explainer"><p>Wähle, wie die Erklärung aufgebaut sein soll. Der Lehrplan bleibt die Grenze; der KI-Erklärer darf keine neuen Anforderungen erfinden.</p><div class="v87-ai-levels">'+levels.map(function(x,i){return'<button class="btn sm" data-l="'+i+'">'+esc(x)+'</button>';}).join('')+'</div><textarea class="v87-ai-question" placeholder="Was genau ist noch unklar?"></textarea><div class="row"><button class="btn go" id="v87-ai-send">Erklärung anfordern</button><button class="btn" id="v87-ai-copy">Anfrage kopieren</button></div><div class="v87-ai-output" hidden></div></div>';openModal('KI-Tutor: '+concept,'Optional, ohne Schlüssel im HTML.',html,'');var modal=document.getElementById('v87-modal'),sel=0;modal.querySelectorAll('[data-l]').forEach(function(b){b.onclick=function(){sel=+b.dataset.l;modal.querySelectorAll('[data-l]').forEach(function(x){x.classList.toggle('go',x===b);});};});function prompt(){var q=modal.querySelector('.v87-ai-question').value.trim();return'Erkläre auf Schweizer Standarddeutsch, klar und ohne Denglisch. Niveau: '+levels[sel]+'. Abschluss: '+((M.activeProgram&&M.activeProgram())||'')+'. Fach: '+c.subject+'. Kapitel: '+c.title+'. Abschnitt: '+concept+'. Verbindliche Lernziele: '+(c.objectives||[]).join(' | ')+'. Freigegebener Kontext: '+body+'. Frage der lernenden Person: '+(q||'Erkläre den Zusammenhang vollständig.')+'. Erfinde keine zusätzlichen Lehrplananforderungen. Wenn der Kontext nicht reicht, sage das offen.';}modal.querySelector('#v87-ai-copy').onclick=function(){navigator.clipboard&&navigator.clipboard.writeText(prompt());var o=modal.querySelector('.v87-ai-output');o.hidden=false;o.textContent='Die Anfrage wurde kopiert.';};modal.querySelector('#v87-ai-send').onclick=async function(){var endpoint=(window.MNEMIKA&&MNEMIKA.kiEndpoint)?MNEMIKA.kiEndpoint():''; /* R128 (GH-A): kein localStorage-Endpunkt */var o=modal.querySelector('.v87-ai-output');o.hidden=false;if(!endpoint){o.textContent='Es ist noch kein KI-Endpunkt eingerichtet. Kopiere die vorbereitete Anfrage und verwende sie in einem freigegebenen KI-Dienst.';return;}o.textContent='Die Erklärung wird erstellt …';try{var r=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:prompt(),degree:(M.activeProgram&&M.activeProgram())||'',subject:c.subject,chapter_id:c.id,section:concept})});if(!r.ok)throw new Error('HTTP '+r.status);var ct=r.headers.get('content-type')||'',data=ct.includes('json')?await r.json():await r.text();o.textContent=typeof data==='string'?data:(data.text||data.answer||JSON.stringify(data));}catch(e){o.textContent='Der KI-Tutor ist derzeit nicht erreichbar. '+e.message;}};}
var baseInline=M.inlineCheck&&M.inlineCheck.bind(M);if(baseInline){M.inlineCheck=function(host,q){var c=srcChapter(q&&q.lessonId)||{id:q&&q.lessonId||'check',title:q&&q.unit||'Zwischencheck',subject:q&&q.subject||'orientation',objectives:[]};var r=baseInline(host,q);if(host&&!host.querySelector(':scope > .v87-coach')){host.insertAdjacentHTML('afterbegin',coach(c,'check','Bevor du antwortest',checkMessage(q),String(q.id)+'|check',true));}if(host&&q&&!host.dataset.v87Watch){host.dataset.v87Watch='1';var ob=new MutationObserver(function(){var fb=host.querySelector('.fb.ok,.fb.no');if(!fb)return;var ok=fb.classList.contains('ok'),msg=firstSentence(q.explanation||fb.textContent);var old=host.querySelector(':scope > .v87-coach');if(old)old.remove();host.insertAdjacentHTML('afterbegin',coach(c,ok?'ok':'no',ok?'Der entscheidende Schritt stimmt':'Hier liegt der erste Fehler',ok?('Deine Antwort trifft den fachlichen Kern. '+msg):('Prüfe genau die Bedingung, an der sich die beiden Möglichkeiten unterscheiden. '+msg),String(q.id)+'|'+ok,true));ob.disconnect();});ob.observe(host,{childList:true,subtree:true});}return r;};}
